{
  "items": [
    {
      "title": "German Environment Agency (UBA) – Environmental Data Portal",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data",
      "justification": "Official environmental data portal maintained by Germany's Federal Environment Agency (Umweltbundesamt). Provides access to datasets, environmental indicators, trends, and assessments covering Germany during the 2020s. Topics include air pollution, water quality, soil conditions, biodiversity, climate change, and environmental pressures. Particularly useful for studying national environmental conditions and their evolution from 2020 onward."
    },
    {
      "title": "German Weather Service (DWD) – Climate Data Center",
      "url_or_doi": "https://opendata.dwd.de/climate_environment/CDC/",
      "justification": "Official open-data repository operated by the Deutscher Wetterdienst (DWD). Provides meteorological observations and climate datasets covering Germany throughout the 2020s. Variables include air temperature, precipitation, humidity, wind, sunshine duration, and other climatic measurements. Includes historical and recent observations at different temporal resolutions. Suitable for analyzing climate variability, extreme weather, droughts, and environmental changes between 2020 and 2026."
    },
    {
      "title": "German Environment Agency – Air Quality in Germany Open Data",
      "url_or_doi": "https://luftdaten.umweltbundesamt.de/index.php/en/air-quality-germany-open-data-everyone",
      "justification": "Official air-quality monitoring dataset provided by the German Environment Agency. Contains measurements from monitoring stations across Germany, including observations collected during the 2020s. Covers atmospheric pollutants such as particulate matter (PM10 and PM2.5), nitrogen dioxide, and ozone. Data can be accessed through downloadable resources and APIs. Useful for studying air pollution, environmental exposure, regional differences, and changes in atmospheric conditions."
    },
    {
      "title": "German Environment Agency – Air Data API",
      "url_or_doi": "https://www.umweltbundesamt.de/daten/luft/luftdaten/doc",
      "justification": "Official API providing programmatic access to German air-quality monitoring data. The documented data service includes observations beginning in 2016, covering the 2020s. Enables researchers to retrieve measurements by monitoring station, pollutant, and observation period. Particularly useful for constructing reproducible datasets on air pollution trends, atmospheric environmental quality, and differences between urban and rural locations."
    },
    {
      "title": "German Weather Service – Monthly Climate Station Observations",
      "url_or_doi": "https://opendata.dwd.de/climate_environment/CDC/observations_germany/climate/monthly/kl/historical/",
      "justification": "Official dataset of monthly climate observations collected at meteorological stations throughout Germany. Contains historical climate records that include observations from the 2020s. Suitable for analyzing temperature patterns, precipitation variability, seasonal environmental conditions, and long-term climate trends. Station-level observations allow comparisons between different geographical regions of Germany."
    },
    {
      "title": "German Weather Service – Hourly Air Temperature Observations",
      "url_or_doi": "https://opendata.dwd.de/climate_environment/CDC/observations_germany/climate/hourly/air_temperature/recent/",
      "justification": "Official dataset containing recent hourly air-temperature measurements from meteorological stations across Germany. Provides high-temporal-resolution observations relevant to the 2020s. Useful for studying heatwaves, temperature extremes, daily temperature variability, seasonal changes, and local climate conditions. Particularly relevant for research on climate-related environmental hazards."
    },
    {
      "title": "German Environment Agency – Environmental Monitor 2024",
      "url_or_doi": "https://www.umweltbundesamt.de/en/publikationen/environmental-monitor-2024",
      "justification": "Official environmental indicator publication released in 2024 by the German Environment Agency. Presents 30 environmental indicators describing environmental conditions, pollution pressures, and environmental policy objectives in Germany. Includes information concerning air quality, climate change, natural resources, and other environmental topics. Useful for identifying environmental trends and locating supporting indicator data relevant to the early 2020s. This is an indicator report rather than a standalone raw dataset."
    },
    {
      "title": "German Environment Agency – Environmental Indicators and Customized Reports",
      "url_or_doi": "https://www.umweltbundesamt.de/en/data/environment-indicators/report",
      "justification": "Official environmental indicator platform providing access to indicators describing Germany's environmental conditions. Supports the exploration of environmental trends, including information relevant to the 2020s. Particularly useful for studying air quality, environmental pressures, climate-related indicators, and progress toward environmental objectives. The platform allows researchers to create customized environmental indicator reports."
    },
    {
      "title": "Helmholtz Centre for Environmental Research – Water Quality and Quantity Database Germany, Version 2",
      "url_or_doi": "https://www.ufz.de/record/dmp/archive/16457/en/",
      "justification": "Research dataset published by the Helmholtz Centre for Environmental Research (UFZ) in January 2026. Contains quality-assured water-quality observations from Germany, organized as CSV data with supporting station metadata and documentation. The dataset record identifies a creation period extending from 2020 to January 2026. Relevant for investigating freshwater environmental conditions, water chemistry, pollution, and spatial differences in water quality. Access permissions are limited, so availability should be checked before use."
    },
    {
      "title": "High-Resolution Daily Climate Time Series for Germany (1981–2100)",
      "url_or_doi": "https://zenodo.org/records/20201156",
      "justification": "Open research dataset published in August 2026 containing high-resolution daily climate time series for Germany. Covers the historical period and future climate scenarios through 2100, including the 2020s. Provides climate information derived from EURO-CORDEX projections and bias correction using observations from the German Weather Service. The original spatial resolution is approximately 1 km. Useful for investigating climate conditions, environmental change, and potential climate impacts on German ecosystems. The 2020s should be interpreted in the context of modeled climate projections rather than exclusively direct observations."
    },
    {
      "title": "German Environment Agency – Environmental Data and Trends",
      "url_or_doi": "https://www.umweltbundesamt.de/daten",
      "justification": "German-language environmental data portal providing comprehensive access to environmental observations, statistics, indicators, maps, and assessments for Germany. Includes current and historical environmental information relevant to the period beginning in 2020. Covers environmental themes such as climate, air, water, soil, natural resources, and environmental pollution. Particularly useful for locating more detailed German-language datasets and official environmental statistics."
    },
    {
      "title": "German National Environmental Information Portal – umwelt.info",
      "url_or_doi": "https://umwelt.info/en/",
      "justification": "National environmental information platform coordinated by the German Environment Agency. Aggregates environmental datasets and information from multiple German institutions and data providers. Supports discovering data on natural environmental conditions, ecosystems, biodiversity, climate, water, and environmental monitoring. Useful for identifying geographically specific and nationally relevant datasets covering the 2020s. This is a dataset discovery portal rather than a single dataset."
    },
    {
      "title": "University of Hamburg – Integrated Climate Data Center: Climate Data for Germany from DWD Stations",
      "url_or_doi": "https://www.geo.uni-hamburg.de/en/service/icdc/data/atmosphere/dwd-station.html",
      "justification": "Academic climate-data resource describing observational datasets from German Weather Service meteorological stations. Provides access information for temperature, precipitation, sunshine duration, and other climate measurements from stations across Germany. Relevant for analyzing regional climatic conditions and environmental changes during the 2020s, subject to the temporal coverage of the individual data series. Particularly useful for long-term climate comparisons and regional environmental research."
    }
  ]
}
